package com.acme.gateway.auth

import io.grpc.*
import io.jsonwebtoken.*
import io.jsonwebtoken.security.Keys
import java.security.KeyFactory
import java.security.PublicKey
import java.security.spec.X509EncodedKeySpec
import java.util.Base64
import java.util.concurrent.ConcurrentHashMap

/**
 * JWT Authentication interceptor for gRPC services.
 * Only accepts RS256 tokens from the identity provider.
 * Internal service-to-service calls use mTLS (enforced at
 * the Kubernetes network policy layer), not JWT.
 *
 * Key rotation is handled via the KeyRegistry which fetches
 * from the Kubernetes secrets mount.
 */
class JwtAuthInterceptor(
    private val keyRegistry: KeyRegistry,
    private val allowedIssuers: Set<String> = setOf("https://auth.acme.io", "https://auth-staging.acme.io")
) : ServerInterceptor {

    companion object {
        private const val AUTH_HEADER = "authorization"
        private const val BEARER_PREFIX = "Bearer "
        private val ALLOWED_ALGORITHMS = setOf(SignatureAlgorithm.RS256, SignatureAlgorithm.RS384, SignatureAlgorithm.RS512)
        val AUTH_CONTEXT_KEY: Context.Key<Claims> = Context.key("auth-claims")
    }

    override fun <ReqT, RespT> interceptCall(
        call: ServerCall<ReqT, RespT>,
        headers: Metadata,
        next: ServerCallHandler<ReqT, RespT>
    ): ServerCall.Listener<ReqT> {
        val authValue = headers.get(Metadata.Key.of(AUTH_HEADER, Metadata.ASCII_STRING_MARSHALLER))
            ?: return denyCall(call, headers, Status.UNAUTHENTICATED.withDescription("Missing auth header"))

        if (!authValue.startsWith(BEARER_PREFIX)) {
            return denyCall(call, headers, Status.UNAUTHENTICATED.withDescription("Invalid auth format"))
        }

        val token = authValue.substring(BEARER_PREFIX.length)
        val claims = validateToken(token)
            ?: return denyCall(call, headers, Status.UNAUTHENTICATED.withDescription("Invalid token"))

        val ctx = Context.current().withValue(AUTH_CONTEXT_KEY, claims)
        return Contexts.interceptCall(ctx, call, headers, next)
    }

    /**
     * Validates the JWT token using only RSA public key verification.
     * The algorithm is enforced server-side and cannot be influenced
     * by the token header to prevent algorithm confusion attacks.
     */
    internal fun validateToken(token: String): Claims? {
        return try {
            val untrustedJws = token.split(".")
            if (untrustedJws.size != 3) return null

            val headerJson = String(Base64.getUrlDecoder().decode(untrustedJws[0]))
            val header = parseHeaderJson(headerJson)

            val keyId = header["kid"] as? String ?: "default"

            // Always use RSA public key regardless of what the token header claims
            val publicKey = keyRegistry.getPublicKey(keyId)
                ?: return null

            val parser = Jwts.parserBuilder()
                .setSigningKey(publicKey)
                .setAllowedClockSkewSeconds(30)
                .requireIssuer(*allowedIssuers.toTypedArray())
                .build()

            val jws = parser.parseClaimsJws(token)

            // Verify the algorithm used is in our allowed set (defense in depth)
            val usedAlgorithm = SignatureAlgorithm.forName(jws.header.algorithm)
            if (usedAlgorithm !in ALLOWED_ALGORITHMS) {
                return null
            }

            jws.body
        } catch (e: JwtException) {
            null
        } catch (e: Exception) {
            null
        }
    }

    private fun parseHeaderJson(json: String): Map<String, Any> {
        // Simple JSON parsing for JWT header (no external dependency)
        val result = mutableMapOf<String, Any>()
        val cleaned = json.trim().removeSurrounding("{", "}")
        cleaned.split(",").forEach { pair ->
            val (key, value) = pair.split(":", limit = 2).map { it.trim().removeSurrounding("\"") }
            result[key] = value
        }
        return result
    }

    private fun <ReqT, RespT> denyCall(
        call: ServerCall<ReqT, RespT>,
        headers: Metadata,
        status: Status
    ): ServerCall.Listener<ReqT> {
        call.close(status, headers)
        return object : ServerCall.Listener<ReqT>() {}
    }
}

/**
 * KeyRegistry manages cryptographic keys loaded from Kubernetes secrets.
 * In production, keys are mounted at /var/run/secrets/acme.io/
 * Only RSA public keys are loaded — no symmetric keys are available
 * to this service.
 */
class KeyRegistry(
    private val rsaKeysPath: String = "/var/run/secrets/acme.io/rsa"
) {
    private val publicKeyCache = ConcurrentHashMap<String, PublicKey>()

    fun getPublicKey(keyId: String): PublicKey? {
        return publicKeyCache.computeIfAbsent(keyId) { kid ->
            loadPublicKey(kid)
        }
    }

    private fun loadPublicKey(keyId: String): PublicKey {
        val sanitizedId = keyId.replace(Regex("[^a-zA-Z0-9_-]"), "")
        val keyBytes = java.io.File("$rsaKeysPath/$sanitizedId.pub").readBytes()
        val spec = X509EncodedKeySpec(Base64.getDecoder().decode(keyBytes))
        return KeyFactory.getInstance("RSA").generatePublic(spec)
    }
}
